/**
 * The harness of the Dart `test/talk_bulk_test.dart`: patterned payloads,
 * generated byte sources, a client and a server Talk channel over one fake
 * mux connection pair with bulk routing on both sides (`Peers`), a byte
 * source the test feeds by hand (Dart's `StreamController<List<int>>`),
 * and polling until a condition holds.
 */

import { onTestFinished } from 'vitest';
import type { MuxOptions } from '../../../src/core/mux/contract.ts';
import type { TalkOptions } from '../../../src/core/talk/contract.ts';
import { installBulkRouting } from '../../../src/core/talk/talk-bulk-routes.ts';
import { TalkChannel } from '../../../src/core/talk/talk-channel.ts';
import { Deferred } from '../../../src/core/util/deferred.ts';
import { type FakeMuxConnection, fakeMuxPair } from './fake-channel.ts';

/** Bytes 0, 1, 2, ... modulo 251, from [offset], so that misplaced chunks show. */
export function pattern(length: number, offset = 0): Uint8Array {
  const out = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    out[i] = (offset + i) % 251;
  }
  return out;
}

/**
 * [total] bytes of {@link pattern} in pieces of `piece` (default 10 000),
 * generated as they are read; `produced` counts what was generated.
 */
export async function* generated(
  total: number,
  options: { piece?: number; produced?: (bytes: number) => void } = {},
): AsyncGenerator<Uint8Array> {
  const piece = options.piece ?? 10_000;
  let offset = 0;
  while (offset < total) {
    const n = total - offset < piece ? total - offset : piece;
    options.produced?.(n);
    yield pattern(n, offset);
    offset += n;
  }
}

/** Collects a stream (or any async iterable) of byte chunks into one array. */
export async function collect(
  stream: ReadableStream<Uint8Array> | AsyncIterable<Uint8Array>,
): Promise<Uint8Array> {
  const parts: Uint8Array[] = [];
  if (stream instanceof ReadableStream) {
    const reader = stream.getReader();
    for (;;) {
      const { value, done } = await reader.read();
      if (done) {
        break;
      }
      parts.push(value);
    }
  } else {
    for await (const chunk of stream) {
      parts.push(chunk);
    }
  }
  return concat(parts);
}

/** [parts] joined. */
export function concat(parts: readonly Uint8Array[]): Uint8Array {
  let total = 0;
  for (const part of parts) {
    total += part.length;
  }
  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

/**
 * Polls [condition] until it holds, at most [timeout] ms of real time
 * (default 2 s). Each poll lets one event loop turn run: what the fake mux
 * and Talk have in flight settles within a few.
 */
export async function until(condition: () => boolean, timeout = 2000): Promise<void> {
  const deadline = Date.now() + timeout;
  while (!condition()) {
    if (Date.now() > deadline) {
      throw new Error('condition not met');
    }
    await new Promise<void>((resolve) => setImmediate(resolve));
  }
}

/**
 * A client and a server over one fake mux connection pair, each routing the
 * bulk channels its peer opens from the start (Dart's subscriptions calling
 * `TalkChannel.adoptBulk`); the server's channels are Talk channels with
 * `serverOptions`. Both connections close when the test finishes.
 */
export class Peers {
  readonly client: FakeMuxConnection;
  readonly server: FakeMuxConnection;
  readonly serverOptions: Partial<TalkOptions> | undefined;

  private constructor(
    client: FakeMuxConnection,
    server: FakeMuxConnection,
    serverOptions: Partial<TalkOptions> | undefined,
  ) {
    this.client = client;
    this.server = server;
    this.serverOptions = serverOptions;
  }

  /** Connects a pair with the mux `options` of both sides (a `clock`, an `initialWindow`, ...). */
  static async connect(
    init: { options?: Partial<MuxOptions>; serverOptions?: Partial<TalkOptions> } = {},
  ): Promise<Peers> {
    const [client, server] = fakeMuxPair(init.options === undefined ? {} : { mux: init.options });
    installBulkRouting(client);
    installBulkRouting(server);
    const peers = new Peers(client, server, init.serverOptions);
    onTestFinished(() => peers.close());
    return peers;
  }

  /** A Talk channel from the client with `options`, and its server end. */
  async open(init: { options?: Partial<TalkOptions> } = {}): Promise<[TalkChannel, TalkChannel]> {
    const talk = new TalkChannel(this.client.open(new Uint8Array(0)), init.options);
    const raw = await this.server.accept();
    return [talk, new TalkChannel(raw, this.serverOptions)];
  }

  async close(): Promise<void> {
    await this.client.close();
    await this.server.close();
  }
}

/**
 * A byte source fed by hand, as a Dart `StreamController<List<int>>` sent
 * as a bulk payload: {@link stream} is iterated once; {@link hasListener}
 * is true from then until the iteration stopped (`return()`, as cancelling
 * a subscription) or delivered the end.
 */
export class SourceController {
  readonly #chunks: Uint8Array[] = [];
  #closed = false;
  #failed = false;
  #error: unknown;
  #listened = false;
  #listening = false;
  #wake: Deferred<void> | undefined;

  /** The source to send; iterable once. */
  readonly stream: AsyncIterable<Uint8Array> = {
    [Symbol.asyncIterator]: () => this.#listen(),
  };

  /** Something iterates {@link stream} and has not stopped nor reached the end. */
  get hasListener(): boolean {
    return this.#listening;
  }

  /** Adds a chunk. */
  add(chunk: Uint8Array): void {
    if (this.#closed) {
      throw new Error('source closed');
    }
    if (this.#listened && !this.#listening) {
      return;
    }
    this.#chunks.push(chunk);
    this.#awaken();
  }

  /** Ends the source with [error], after what was added. */
  addError(error: unknown): void {
    if (this.#closed) {
      throw new Error('source closed');
    }
    this.#closed = true;
    this.#failed = true;
    this.#error = error;
    this.#awaken();
  }

  /** Ends the source after what was added. */
  close(): void {
    this.#closed = true;
    this.#awaken();
  }

  #awaken(): void {
    const wake = this.#wake;
    this.#wake = undefined;
    wake?.resolve();
  }

  #listen(): AsyncIterator<Uint8Array> {
    if (this.#listened) {
      throw new Error('a source is iterated once');
    }
    this.#listened = true;
    this.#listening = true;
    return {
      next: async () => {
        for (;;) {
          if (!this.#listening) {
            return { value: undefined, done: true };
          }
          const chunk = this.#chunks.shift();
          if (chunk !== undefined) {
            return { value: chunk, done: false };
          }
          if (this.#closed) {
            this.#listening = false;
            if (this.#failed) {
              throw this.#error;
            }
            return { value: undefined, done: true };
          }
          const wake = new Deferred<void>();
          this.#wake = wake;
          await wake.promise;
        }
      },
      return: async () => {
        this.#listening = false;
        this.#chunks.length = 0;
        this.#awaken();
        return { value: undefined, done: true };
      },
    };
  }
}

/**
 * A byte source that makes a chunk each time its reader asks for one, as
 * the Dart tests' source fed by a periodic timer while not paused; whether
 * its reader cancelled it shows.
 */
export class PulledSource {
  readonly cancelled = new Deferred<void>();
  readonly stream: ReadableStream<Uint8Array>;

  constructor(make: () => Uint8Array) {
    this.stream = new ReadableStream<Uint8Array>(
      {
        pull: (controller) => controller.enqueue(make()),
        cancel: () => {
          this.cancelled.resolve();
        },
      },
      { highWaterMark: 0 },
    );
  }
}
